use serde_json::json;use std::collections::BTreeMap;
#[derive(Clone,Debug,PartialEq,Eq)]pub struct ResourcePack{pub id:String,pub priority:i32,pub namespaces:Vec<String>,pub generation:u64}
#[derive(Default)]pub struct ResourceLayers{packs:BTreeMap<(i32,String),ResourcePack>,generation:u64}
impl ResourceLayers{pub fn stage(&mut self,p:ResourcePack)->Result<(),String>{if p.id.is_empty()||p.id.len()>128||p.namespaces.iter().any(|n|!valid_ns(n)){return Err("invalid_resource_pack_descriptor".into());}if self.packs.values().any(|v|v.id==p.id){return Err("duplicate_resource_pack_id".into());}self.packs.insert((p.priority,p.id.clone()),p);Ok(())}pub fn begin_reload(&mut self)->u64{self.generation=self.generation.saturating_add(1);self.generation}pub fn report(&self)->serde_json::Value{json!({"mode":"resource-layer-contract-only","reload_applied_to_horizon":false,"generation":self.generation,"packs":self.packs.values().map(|p|json!({"id":p.id,"priority":p.priority,"namespaces":p.namespaces,"generation":p.generation})).collect::<Vec<_>>()})}}
fn valid_ns(v:&str)->bool{!v.is_empty()&&v.len()<=64&&v.bytes().all(|b|b.is_ascii_lowercase()||b.is_ascii_digit()||matches!(b,b'_'|b'-'|b'.'))}
